<?php
declare(strict_types=1);namespace App\Http\Controllers\Hrd;use App\Http\Controllers\Controller;use App\Http\Requests\Hrd\StoreLeaveRequest;use App\Models\PersonnelLeaveRequest;use App\Services\Hrd\LeaveService;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Facades\Storage;use Illuminate\Validation\ValidationException;use Illuminate\View\View;
class PersonnelLeaveController extends Controller{public function index(Request$r):View{$q=PersonnelLeaveRequest::with(['personnel','approver'])->latest();if(!$r->user()->can('personnel-leave.view-all')){$p=$r->user()->personnel;if(!$p)abort(403);$q->where('personnel_id',$p->id);}return view('hrd.leave.index',['title'=>'Izin & Cuti','leaves'=>$q->paginate(20)]);}public function store(StoreLeaveRequest$r):RedirectResponse{$p=$r->user()->personnel;if(!$p)abort(403);$v=$r->validated();$overlap=$p->leaveRequests()->whereIn('status',['pending','approved'])->where('start_date','<=',$v['end_date'])->where('end_date','>=',$v['start_date'])->exists();if($overlap)throw ValidationException::withMessages(['start_date'=>'Rentang tanggal bertumpang tindih dengan pengajuan lain.']);$path=$r->file('attachment')?->store('hrd/leave-attachments','local');$leave=$p->leaveRequests()->create([...collect($v)->except('attachment')->all(),'attachment_path'=>$path]);activity('hrd')->causedBy($r->user())->performedOn($leave)->log('Pegawai mengajukan izin/cuti.');return back()->with('status','Pengajuan berhasil dikirim.');}public function approve(PersonnelLeaveRequest$l,Request$r,LeaveService$s):RedirectResponse{$s->approve($l,$r->user());return back()->with('status','Pengajuan disetujui dan absensi disinkronkan.');}public function reject(PersonnelLeaveRequest$l,Request$r):RedirectResponse{$r->validate(['rejection_note'=>'required|string|max:1000']);if($l->status!=='pending')throw ValidationException::withMessages(['status'=>'Pengajuan sudah diputuskan.']);$l->update(['status'=>'rejected','rejection_note'=>$r->rejection_note]);activity('hrd')->causedBy($r->user())->performedOn($l)->log('HRD menolak izin/cuti.');return back()->with('status','Pengajuan ditolak.');}public function cancel(PersonnelLeaveRequest$l,Request$r):RedirectResponse{if($l->personnel_id!==$r->user()->personnel?->id||$l->status!=='pending')abort(403);$l->update(['status'=>'cancelled']);return back()->with('status','Pengajuan dibatalkan.');}public function attachment(PersonnelLeaveRequest$l,Request$r){if(!$r->user()->can('personnel-leave.view-all')&&$l->personnel_id!==$r->user()->personnel?->id)abort(403);abort_unless($l->attachment_path&&Storage::disk('local')->exists($l->attachment_path),404);return Storage::disk('local')->download($l->attachment_path);}}
